// Digest a captured conversation JSONL: real dialogue + tool-call skeleton + timings.
import { createInterface } from 'node:readline';
const mode = process.argv[2] || 'full';
const rl = createInterface({ input: process.stdin, crlfDelay: Infinity });
let prevTs = null, first = null, last = null, nTool = 0, nAsst = 0, nUser = 0;
const gaps = [];
const out = [];
const clip = (s, n) => { s = String(s).replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n) + '…' : s; };
for await (const line of rl) {
  if (!line.trim()) continue;
  let e; try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp; if (!ts) continue;
  if (!first) first = ts; last = ts;
  const t = Date.parse(ts);
  if (prevTs !== null) { const d = (t - prevTs) / 1000; if (d >= 25) gaps.push([ts, d.toFixed(0)]); }
  prevTs = t;
  const hm = ts.slice(11, 19);
  const c = e.message?.content;
  if (e.type === 'user' && Array.isArray(c)) {
    const texts = c.filter(b => b.type === 'text').map(b => b.text).join('\n');
    if (texts.trim()) { nUser++; out.push(`[${hm}] USER: ${clip(texts, mode === 'full' ? 2500 : 600)}`); }
    for (const b of c) if (b.type === 'tool_result' && b.is_error) out.push(`[${hm}]   !! TOOL_ERROR: ${clip(typeof b.content === 'string' ? b.content : JSON.stringify(b.content), 400)}`);
  } else if (e.type === 'user' && typeof c === 'string') {
    nUser++; out.push(`[${hm}] USER: ${clip(c, mode === 'full' ? 2500 : 600)}`);
  } else if (e.type === 'assistant' && Array.isArray(c)) {
    for (const b of c) {
      if (b.type === 'text' && b.text.trim()) { nAsst++; out.push(`[${hm}] ASST: ${clip(b.text, mode === 'full' ? 1200 : 400)}`); }
      if (b.type === 'tool_use') {
        nTool++;
        const i = b.input || {};
        const arg = i.command || i.file_path || i.pattern || i.path || i.prompt || i.description || i.body || i.query || '';
        out.push(`[${hm}]   > ${b.name}: ${clip(arg, 200)}`);
      }
    }
  }
}
const durMin = first && last ? ((Date.parse(last) - Date.parse(first)) / 60000).toFixed(1) : '?';
console.log(`### span ${first} -> ${last}  (${durMin} min)  user_msgs=${nUser} asst_texts=${nAsst} tool_calls=${nTool}`);
gaps.sort((a, b) => b[1] - a[1]);
console.log(`### top gaps >=25s: ` + gaps.slice(0, 12).map(g => `${g[0].slice(11, 19)}=${g[1]}s`).join(' '));
console.log(`### total idle in gaps>=25s: ${(gaps.reduce((s, g) => s + +g[1], 0) / 60).toFixed(1)} min`);
console.log(out.join('\n'));
EOF
